actions.script:
const setup = ec.service.sync().name('ironstone.KnowledgeServices.get#KnowledgeSetup').parameter('wikiSpaceId', wikiSpaceId || null).call()
const openSpaceId = wikiSpaceId || setup.defaultWikiSpaceId || null
spaceList = Array.from(setup.spaceList || []).map((space) => ({spaceId: space.wikiSpaceId, description: space.description || space.wikiSpaceId,
    storageText: space.storageText || '', openText: !wikiPageId && space.wikiSpaceId === openSpaceId ? ec.l10n.localize('Open') : ''}))
page = null
crumbList = []
childList = []
changeText = ''
if (!ec.message.hasError() && (wikiPageId || openSpaceId)) {
    const out = ec.service.sync().name('ironstone.KnowledgeServices.get#PageView').parameters(wikiPageId ? {wikiPageId: wikiPageId}
            : {wikiSpaceId: openSpaceId, pagePath: pagePath || ''}).call()
    if (!ec.message.hasError() && out.page) {
        page = out.page
        crumbList = [{label: page.spaceDescription || page.wikiSpaceId, crumbPath: ''}].concat(Array.from(page.breadcrumbs || [])
                .map((crumb) => ({label: crumb.label, crumbPath: crumb.pagePath})))
        if (page.isRoot) crumbList = []
        const change = page.lastChange
        changeText = change ? [change.dateText, change.userName, change.note].filter((part) => part).join(' · ') : ''
        if (page.exists) {
            const children = ec.service.sync().name('ironstone.KnowledgeServices.get#PageChildren').parameters({wikiSpaceId: page.wikiSpaceId,
                pagePath: page.pagePath || ''}).call()
            if (!ec.message.hasError()) childList = Array.from(children.childList || []).map((child) => ({childSpaceId: page.wikiSpaceId,
                childPath: child.pagePath, name: child.name + (child.hasChildren ? ' …' : ''), restrictedText: child.restricted ? ec.l10n.localize('Restricted') : ''}))
        }
    }
}
